import{_ as d,o as a,c as r,af as n}from"./chunks/framework.B28LkSoM.js";const c=JSON.parse('{"title":"2027事业单位备考·每日执行清单","description":"每天照着做的备考清单：每日时间骨架、必打钩事项、记忆时段安排，以及基础期 8 周逐日详细安排 + 强化冲刺期逐周任务包。","frontmatter":{"title":"2027事业单位备考·每日执行清单","published":"2026-10-04T00:00:00.000Z","tags":["事业单位","备考","学习路线","每日计划","河南"],"description":"每天照着做的备考清单：每日时间骨架、必打钩事项、记忆时段安排，以及基础期 8 周逐日详细安排 + 强化冲刺期逐周任务包。","date":"2026-10-04T00:00:00.000Z","cover":false,"hidden":true},"headers":[],"relativePath":"posts/回收站🗑️/2027事业单位备考每日执行清单.md","filePath":"posts/回收站🗑️/2027事业单位备考每日执行清单.md"}'),s={name:"posts/回收站🗑️/2027事业单位备考每日执行清单.md"};function e(o,t,h,l,i,p){return a(),r("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1791072000000"},[...t[0]||(t[0]=[n(`<blockquote><p>⚠️ <strong>这份已作废（2026-10-20）。</strong> 它是 10/4 写的，前提是&quot;自己排板块 + 不买系统班 + 手写笔记&quot;。 现在的前提变成&quot;粉笔 680 河南班周更 + 平板 + 讲义当底稿&quot;，请改看 <strong><a href="./2027事业单位备考每日执行清单-v2.html">每日执行清单 v2·680双轨版</a></strong>。 保留这份只为留个痕迹，里面的逐日板块和日期都不要再照着做。</p></blockquote><blockquote><p><strong>配套文件</strong>：考试结构、资源清单、学习方法、报名选岗、考场规则、面试体检等全部在《2027事业单位备考规划》里。<strong>这份文件只管一件事：今天做什么。</strong></p></blockquote><p><strong>怎么用</strong>：每天晚上翻到明天那一格，看一眼就行。做完的打钩。</p><hr><h2 id="一、每天必打钩的-9-件事" tabindex="-1">一、每天必打钩的 9 件事 <a class="header-anchor" href="#一、每天必打钩的-9-件事" aria-label="Permalink to &quot;一、每天必打钩的 9 件事&quot;">​</a></h2><p>不管处于哪个阶段，这 9 项每天都要完成：</p><ul><li>[ ] <strong>早起回忆</strong>（20 分钟，不看书，回忆昨天学的骨架）</li><li>[ ] 上午听课</li><li>[ ] 上午精读教材对应章节</li><li>[ ] 上午做对应章节题</li><li>[ ] 下午职测方法课</li><li>[ ] 下午职测限时刷题（<strong>必须计时</strong>）</li><li>[ ] 晚上错题归因（每道错题写一句话：为什么错）</li><li>[ ] 晚上默写今天的骨架清单（30 分钟）</li><li>[ ] 睡前过最难记的清单（15 分钟）</li></ul><p>下面第三节会解释为什么&quot;回忆 / 默写&quot;占了三次。</p><hr><h2 id="二、每日时间骨架" tabindex="-1">二、每日时间骨架 <a class="header-anchor" href="#二、每日时间骨架" aria-label="Permalink to &quot;二、每日时间骨架&quot;">​</a></h2><h3 id="基础期-w1–w8-约-6-5-小时" tabindex="-1">基础期（W1–W8，约 6.5 小时） <a class="header-anchor" href="#基础期-w1–w8-约-6-5-小时" aria-label="Permalink to &quot;基础期（W1–W8，约 6.5 小时）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>07:00–07:30  起床、早饭（不碰手机）</span></span>
<span class="line"><span>07:30–07:50  回忆昨天（不看书，默写或口述）      ← 记忆①</span></span>
<span class="line"><span>08:30–10:00  听课（马克 / 李梦娇）</span></span>
<span class="line"><span>10:00–11:30  教材对应章节精读 + 章节刷题</span></span>
<span class="line"><span>11:30–14:00  午饭 + 午休（必须睡 20–30 分钟）</span></span>
<span class="line"><span>14:00–15:00  职测模块方法论</span></span>
<span class="line"><span>15:00–17:00  职测限时刷题</span></span>
<span class="line"><span>17:00–19:00  晚饭 + 休息（离开书桌）</span></span>
<span class="line"><span>19:00–20:00  错题归因 + 回填框架笔记</span></span>
<span class="line"><span>20:00–20:30  时政</span></span>
<span class="line"><span>20:30–21:00  默写今天的骨架清单                ← 记忆②</span></span>
<span class="line"><span>21:00–21:15  过最难记的部分                     ← 记忆③</span></span>
<span class="line"><span>22:30 前     睡觉（7–8 小时）</span></span></code></pre></div><h3 id="强化期-w9–w25-约-6-5-小时" tabindex="-1">强化期（W9–W25，约 6.5 小时） <a class="header-anchor" href="#强化期-w9–w25-约-6-5-小时" aria-label="Permalink to &quot;强化期（W9–W25，约 6.5 小时）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>07:00–07:30  起床、早饭</span></span>
<span class="line"><span>07:30–07:50  回忆昨天                          ← 记忆①</span></span>
<span class="line"><span>08:00–11:00  公基二轮（听课 / 刷题 / 错题三刷）</span></span>
<span class="line"><span>11:00–14:00  午休</span></span>
<span class="line"><span>14:00–17:30  职测模块刷题 + 限时套卷</span></span>
<span class="line"><span>17:30–19:00  晚饭 + 休息</span></span>
<span class="line"><span>19:00–20:00  作文 或 改错（隔日轮换）</span></span>
<span class="line"><span>20:00–20:30  时政</span></span>
<span class="line"><span>20:30–21:00  默写今天的清单                    ← 记忆②</span></span>
<span class="line"><span>21:00–21:15  过最难记的部分                     ← 记忆③</span></span></code></pre></div><h3 id="冲刺期-w26–w34-约-7-小时" tabindex="-1">冲刺期（W26–W34，约 7 小时） <a class="header-anchor" href="#冲刺期-w26–w34-约-7-小时" aria-label="Permalink to &quot;冲刺期（W26–W34，约 7 小时）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>07:00–07:30  起床、早饭</span></span>
<span class="line"><span>07:30–07:50  回忆昨天                          ← 记忆①</span></span>
<span class="line"><span>08:00–09:40  职测整卷限时（90 分钟，全真）</span></span>
<span class="line"><span>09:50–11:20  公基整卷限时（90 分钟，全真）</span></span>
<span class="line"><span>11:20–14:00  午休</span></span>
<span class="line"><span>14:00–17:00  对答案 + 逐题精析 + 错题归因</span></span>
<span class="line"><span>17:00–19:00  休息</span></span>
<span class="line"><span>19:00–20:00  时政冲刺 / 作文主题打磨</span></span>
<span class="line"><span>20:00–20:30  素材库整理</span></span>
<span class="line"><span>20:30–21:00  过清单（易漏项、易混项）           ← 记忆②③</span></span></code></pre></div><p><strong>每天第一件事永远是先清「到期复习」，再学新知识。宁可少学新，不可欠复习。</strong></p><hr><h2 id="三、关于「要不要专门花时间背」" tabindex="-1">三、关于「要不要专门花时间背」 <a class="header-anchor" href="#三、关于「要不要专门花时间背」" aria-label="Permalink to &quot;三、关于「要不要专门花时间背」&quot;">​</a></h2><p><strong>要花时间，但不能是&quot;抱书朗读一小时&quot;。</strong></p><h3 id="为什么朗读没用" tabindex="-1">为什么朗读没用 <a class="header-anchor" href="#为什么朗读没用" aria-label="Permalink to &quot;为什么朗读没用&quot;">​</a></h3><ol><li><strong>公基考的是辨析，不是默写课文。</strong> 考试不会问你「什么是唯物辩证法」，它会问「下列属于唯物辩证法三大规律的是」。所以背整段文字没用，要背的是<strong>清单和区别</strong>。</li><li><strong>主动回忆 &gt; 反复阅读，这是有研究支撑的。</strong> 认知心理学的权威评级（Dunlosky 等，汇总 61 年研究）把「练习测试」和「分散练习」列为高效用，把「反复阅读」「划线」「摘抄」列为低效用。而且反复阅读会给你「我已经会了」的错觉——合上书就露馅。</li><li>所以<strong>朗读是效率最低的背法</strong>。同样一小时，默写胜过朗读五遍。</li></ol><h3 id="每天一小时-拆成三次回忆" tabindex="-1">每天一小时，拆成三次回忆 <a class="header-anchor" href="#每天一小时-拆成三次回忆" aria-label="Permalink to &quot;每天一小时，拆成三次回忆&quot;">​</a></h3><p>就是你看到的骨架里的 ①②③：</p><table tabindex="0"><thead><tr><th>时段</th><th>时长</th><th>做什么</th></tr></thead><tbody><tr><td>早上 07:30–07:50</td><td>20 分钟</td><td><strong>不看书</strong>，回忆昨天学的骨架，写不出来的做标记</td></tr><tr><td>晚上 20:30–21:00</td><td>30 分钟</td><td>默写今天学的清单（先默后对，红笔补缺口）</td></tr><tr><td>睡前 21:00–21:15</td><td>15 分钟</td><td>只看最难记的部分和标记处（睡眠会巩固记忆）</td></tr></tbody></table><p>加起来 65 分钟，差不多就是你想的「每天一小时」——但形式是回忆和默写，不是朗读。</p><h3 id="哪些内容必须单独抄成「清单卡」" tabindex="-1">哪些内容必须单独抄成「清单卡」 <a class="header-anchor" href="#哪些内容必须单独抄成「清单卡」" aria-label="Permalink to &quot;哪些内容必须单独抄成「清单卡」&quot;">​</a></h3><p>这几类是「原话挖空」型考点，没有理解可借，就是得记死：</p><table tabindex="0"><thead><tr><th>类型</th><th>例子</th><th>怎么记</th></tr></thead><tbody><tr><td>法律的数字</td><td>年龄、期限、比例、金额</td><td>做成一张表 / 数轴，每天过一遍</td></tr><tr><td>并列项</td><td>三大规律、五对范畴、六种行政处分、九种刑罚</td><td>默写清单：先答「几个」，再逐项背，最后数一遍</td></tr><tr><td>公文文种与格式要素</td><td>15 种法定公文、版头主体版记</td><td>对照表，默画</td></tr><tr><td>会议-时间-内容对应</td><td>重要会议、文件、领导人讲话</td><td>时间轴</td></tr><tr><td>时政</td><td>近一年、近半年为重点</td><td>六要素拆解；<strong>考前 1–2 周集中突击</strong></td></tr></tbody></table><p>法律数字要特别注意：<strong>用教材核对，不要用年份久的老视频</strong>（比如《行政处罚法》2021 年修订过）。</p><h3 id="哪些不用背" tabindex="-1">哪些不用背 <a class="header-anchor" href="#哪些不用背" aria-label="Permalink to &quot;哪些不用背&quot;">​</a></h3><p>马原原理、经济供求和货币政策逻辑、法律构成要件的推理——这些是<strong>理解 + 做题</strong>，硬背反而做题时用不上。判断标准：做 3 年真题，反复以「原话挖空」出现的就死记，总是「给情境选原理」的就理解。</p><h3 id="口诀怎么用" tabindex="-1">口诀怎么用 <a class="header-anchor" href="#口诀怎么用" aria-label="Permalink to &quot;口诀怎么用&quot;">​</a></h3><p>口诀只做<strong>提取线索</strong>，必须走「口诀 → 还原全部项 → 真题验证」三步。 比如「行政处分六板斧，警告两过降撤除」（警告、记过、记大过、降级、撤职、开除）——光背口诀不够，要能认出「罚款不是行政处分」才算会，这正是多选题的坑。 口诀只给最容易混、最常考的清单编，<strong>不超过考点的 10–15%</strong>。</p><hr><h2 id="四、每周日的固定动作" tabindex="-1">四、每周日的固定动作 <a class="header-anchor" href="#四、每周日的固定动作" aria-label="Permalink to &quot;四、每周日的固定动作&quot;">​</a></h2><ul><li>[ ] 上午：公文改错 2 篇（三种形式轮换）+ 本周错题重做</li><li>[ ] 下午：<strong>完全休息</strong></li><li>[ ] 晚上：下周计划 + 素材库整理（摘 3–5 条）+ 作文自评</li><li>[ ] 每月最后一个周日：全真模拟（上午职测 90 分钟 + 下午公基 90 分钟）</li></ul><hr><h2 id="五、基础期逐日安排-w1–w8-10-5–11-29" tabindex="-1">五、基础期逐日安排（W1–W8，10/5–11/29） <a class="header-anchor" href="#五、基础期逐日安排-w1–w8-10-5–11-29" aria-label="Permalink to &quot;五、基础期逐日安排（W1–W8，10/5–11/29）&quot;">​</a></h2><h3 id="w1-10-5–10-11-公基-政治·马原-职测-言语·逻辑填空" tabindex="-1">W1（10/5–10/11）公基：政治·马原｜职测：言语·逻辑填空 <a class="header-anchor" href="#w1-10-5–10-11-公基-政治·马原-职测-言语·逻辑填空" aria-label="Permalink to &quot;W1（10/5–10/11）公基：政治·马原｜职测：言语·逻辑填空&quot;">​</a></h3><table tabindex="0"><thead><tr><th>日期</th><th>上午（公基）</th><th>下午（职测）</th><th>晚上 / 备注</th></tr></thead><tbody><tr><td>周一 10/5</td><td>马原·绪论与唯物论（物质、意识、规律）</td><td>逻辑填空方法课</td><td>错题归因 + 默写骨架</td></tr><tr><td>周二 10/6</td><td>马原·辩证法·两大特征（联系、发展）+ 对立统一、质量互变</td><td>逻辑填空 30 题</td><td>同上</td></tr><tr><td>周三 10/7</td><td>马原·辩证法·否定之否定 + 五对范畴</td><td>逻辑填空 30 题</td><td>同上</td></tr><tr><td>周四 10/8</td><td>马原·认识论（实践与认识、真理）</td><td>逻辑填空 30 题</td><td>同上</td></tr><tr><td>周五 10/9</td><td>马原·唯物史观（社会存在/意识、生产力/生产关系、经济基础/上层建筑、人民群众）</td><td>逻辑填空 30 题</td><td>同上</td></tr><tr><td>周六 10/10</td><td>马原全章错题重做 + 默写马原框架</td><td>逻辑填空 30 题</td><td>19:00–20:00 看作文结构课（醒醒最厉害），拆解 2023 真题范文，<strong>只写提纲不写全文</strong></td></tr><tr><td>周日 10/11</td><td>错题重做 + 马原清单默写</td><td>休息</td><td>素材库起步（摘 3 条）+ 下周计划</td></tr></tbody></table><p><strong>本周目标</strong>：能合上书默写马原四大块的二级标题，以及三大规律、五对范畴具体是什么。</p><h3 id="w2-10-12–10-18-公基-政治·毛概-中特-习思想-职测-言语·片段阅读" tabindex="-1">W2（10/12–10/18）公基：政治·毛概+中特+习思想｜职测：言语·片段阅读 <a class="header-anchor" href="#w2-10-12–10-18-公基-政治·毛概-中特-习思想-职测-言语·片段阅读" aria-label="Permalink to &quot;W2（10/12–10/18）公基：政治·毛概+中特+习思想｜职测：言语·片段阅读&quot;">​</a></h3><table tabindex="0"><thead><tr><th>日期</th><th>上午（公基）</th><th>下午（职测）</th><th>晚上 / 备注</th></tr></thead><tbody><tr><td>周一 10/12</td><td>毛概·新民主主义革命（三座大山、三大法宝、活的灵魂）</td><td>片段阅读·主旨题方法</td><td>错题归因 + 默写</td></tr><tr><td>周二 10/13</td><td>毛概·社会主义改造与建设</td><td>片段阅读 30 题</td><td>同上</td></tr><tr><td>周三 10/14</td><td>中特·邓小平理论 + 三个代表 + 科学发展观</td><td>片段阅读 30 题</td><td>同上</td></tr><tr><td>周四 10/15</td><td>习思想·核心要义（十个明确、十四个坚持）</td><td>片段阅读 30 题</td><td>同上</td></tr><tr><td>周五 10/16</td><td>习思想·战略布局（四个全面、五位一体、新发展理念）</td><td>片段阅读 30 题</td><td>同上</td></tr><tr><td>周六 10/17</td><td>本章错题 + 默写中特理论时间轴</td><td>片段阅读 30 题</td><td>19:00–20:00 <strong>写第 1 篇完整作文</strong>（手写、限时 50 分钟、1000 字）</td></tr><tr><td>周日 10/18</td><td>改错课 1–6 集（公考李致）+ 错题重做</td><td>休息</td><td>作文对照范文自评 + 下调计划</td></tr></tbody></table><h3 id="w3-10-19–10-25-公基-政治·时政-职测-言语·语句表达-限时" tabindex="-1">W3（10/19–10/25）公基：政治·时政｜职测：言语·语句表达 + 限时 <a class="header-anchor" href="#w3-10-19–10-25-公基-政治·时政-职测-言语·语句表达-限时" aria-label="Permalink to &quot;W3（10/19–10/25）公基：政治·时政｜职测：言语·语句表达 + 限时&quot;">​</a></h3><table tabindex="0"><thead><tr><th>日期</th><th>上午（公基）</th><th>下午（职测）</th><th>晚上 / 备注</th></tr></thead><tbody><tr><td>周一 10/19</td><td>时政·考什么、什么范围（近一年、近半年重点）+ 马克时政课开场</td><td>语句表达·句子填空</td><td>错题归因 + 默写</td></tr><tr><td>周二 10/20</td><td>时政·2026 年 7–9 月月度梳理</td><td>语句表达·句子排序</td><td>同上</td></tr><tr><td>周三 10/21</td><td>时政·2025 年重点回顾（会议、文件）</td><td>言语限时套题（30 题计时）</td><td>同上</td></tr><tr><td>周四 10/22</td><td>时政·河南省情（十大战略、本地政策）</td><td>言语限时套题</td><td>同上</td></tr><tr><td>周五 10/23</td><td>时政·近期重要讲话与重大成就</td><td>言语限时套题</td><td>同上</td></tr><tr><td>周六 10/24</td><td>时政清单默写 + 错题</td><td>言语限时套题</td><td>19:00–20:00 作文 1 篇</td></tr><tr><td>周日 10/25</td><td>改错 2 篇（病句 / 错别字形式）+ 错题重做</td><td>休息</td><td>作文自评 + 素材库 3 条</td></tr></tbody></table><h3 id="w4-10-26–11-1-公基-法律·宪法-法理-行政法-职测-判断·图形推理" tabindex="-1">W4（10/26–11/1）公基：法律·宪法 + 法理 + 行政法｜职测：判断·图形推理 <a class="header-anchor" href="#w4-10-26–11-1-公基-法律·宪法-法理-行政法-职测-判断·图形推理" aria-label="Permalink to &quot;W4（10/26–11/1）公基：法律·宪法 + 法理 + 行政法｜职测：判断·图形推理&quot;">​</a></h3><table tabindex="0"><thead><tr><th>日期</th><th>上午（公基）</th><th>下午（职测）</th><th>晚上 / 备注</th></tr></thead><tbody><tr><td>周一 10/26</td><td>宪法·国家制度与国家机构</td><td>图推·位置类（平移、旋转、翻转）</td><td>错题归因 + 默写</td></tr><tr><td>周二 10/27</td><td>宪法·公民基本权利与义务</td><td>图推·样式类（加减同异、黑白运算）</td><td>同上</td></tr><tr><td>周三 10/28</td><td>法理·法的效力位阶、法律关系、法律责任</td><td>图推·属性类（对称、曲直、开闭）</td><td>同上</td></tr><tr><td>周四 10/29</td><td>行政法·行政行为、行政许可、行政处罚</td><td>图推·数量类（点线面角素）</td><td>同上</td></tr><tr><td>周五 10/30</td><td>行政法·行政强制、行政复议、行政诉讼</td><td>图推·立体折叠（相对面、相邻面、箭头法）</td><td>同上</td></tr><tr><td>周六 10/31</td><td>本章错题 + 做「行政处罚 vs 行政处分」对比表</td><td>图推 20 题</td><td>19:00–20:00 作文 1 篇</td></tr><tr><td>周日 11/1</td><td>改错 2 篇（公文格式形式）+ 错题重做</td><td>休息</td><td>作文自评 + 素材库</td></tr></tbody></table><h3 id="w5-11-2–11-8-公基-法律·民法-刑法-职测-判断·定义-类比" tabindex="-1">W5（11/2–11/8）公基：法律·民法 + 刑法｜职测：判断·定义 + 类比 <a class="header-anchor" href="#w5-11-2–11-8-公基-法律·民法-刑法-职测-判断·定义-类比" aria-label="Permalink to &quot;W5（11/2–11/8）公基：法律·民法 + 刑法｜职测：判断·定义 + 类比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>日期</th><th>上午（公基）</th><th>下午（职测）</th><th>晚上 / 备注</th></tr></thead><tbody><tr><td>周一 11/2</td><td>民法·民事主体（权利能力、行为能力）、民事法律行为</td><td>定义判断方法</td><td>错题归因 + 默写</td></tr><tr><td>周二 11/3</td><td>民法·物权、合同、侵权责任</td><td>定义判断 20 题</td><td>同上</td></tr><tr><td>周三 11/4</td><td>民法·婚姻家庭、继承</td><td>定义判断 20 题</td><td>同上</td></tr><tr><td>周四 11/5</td><td>刑法·犯罪构成、故意犯罪的停止形态（未遂 vs 中止）</td><td>类比推理·并列 / 包容 / 对应</td><td>同上</td></tr><tr><td>周五 11/6</td><td>刑法·刑罚种类（主刑 / 附加刑）、常见罪名</td><td>类比推理 20 题</td><td><strong>今天教资笔试出分</strong></td></tr><tr><td>周六 11/7</td><td>法律错题 + 做「数字表」（年龄线、期限线）</td><td>判断混合 20 题</td><td>19:00–20:00 作文 1 篇</td></tr><tr><td>周日 11/8</td><td>改错 2 篇 + 错题重做</td><td>休息</td><td>下周计划；<strong>教资过了就报面试</strong>（报名约 11/8–11）</td></tr></tbody></table><h3 id="w6-11-9–11-15-公基-法律·诉讼法-公司法-其他-职测-判断·逻辑判断" tabindex="-1">W6（11/9–11/15）公基：法律·诉讼法 + 公司法 + 其他｜职测：判断·逻辑判断 <a class="header-anchor" href="#w6-11-9–11-15-公基-法律·诉讼法-公司法-其他-职测-判断·逻辑判断" aria-label="Permalink to &quot;W6（11/9–11/15）公基：法律·诉讼法 + 公司法 + 其他｜职测：判断·逻辑判断&quot;">​</a></h3><table tabindex="0"><thead><tr><th>日期</th><th>上午（公基）</th><th>下午（职测）</th><th>晚上 / 备注</th></tr></thead><tbody><tr><td>周一 11/9</td><td>民事诉讼法（管辖、证据、程序）</td><td>逻辑判断·翻译推理</td><td>错题归因 + 默写</td></tr><tr><td>周二 11/10</td><td>刑事诉讼法、行政诉讼法</td><td>翻译推理练习</td><td>同上</td></tr><tr><td>周三 11/11</td><td>公司法（设立、组织机构、股东权利）</td><td>逻辑判断·加强削弱</td><td>同上</td></tr><tr><td>周四 11/12</td><td>其他：劳动法、消费者权益保护法、治安管理处罚法</td><td>加强削弱练习</td><td>同上</td></tr><tr><td>周五 11/13</td><td>法律全板块错题 + 对比表汇总</td><td>逻辑判断混合 20 题</td><td>同上</td></tr><tr><td>周六 11/14</td><td>法律框架默写清单（六大法律）</td><td>判断推理 30 题</td><td>19:00–20:00 作文 1 篇</td></tr><tr><td>周日 11/15</td><td>改错 2 篇 + 错题重做</td><td>休息</td><td>作文自评 + 素材库</td></tr></tbody></table><h3 id="w7-11-16–11-22-公基-经济-职测-资料分析" tabindex="-1">W7（11/16–11/22）公基：经济｜职测：资料分析 <a class="header-anchor" href="#w7-11-16–11-22-公基-经济-职测-资料分析" aria-label="Permalink to &quot;W7（11/16–11/22）公基：经济｜职测：资料分析&quot;">​</a></h3><table tabindex="0"><thead><tr><th>日期</th><th>上午（公基）</th><th>下午（职测）</th><th>晚上 / 备注</th></tr></thead><tbody><tr><td>周一 11/16</td><td>经济·市场经济基础（供求、价格、市场机制）</td><td>资料分析·公式默写（增长量、增长率）</td><td>错题归因 + 默写</td></tr><tr><td>周二 11/17</td><td>经济·宏观经济（GDP、CPI、财政政策、货币政策）</td><td>资料分析·比重、平均数、倍数</td><td>同上</td></tr><tr><td>周三 11/18</td><td>经济·微观（消费者、厂商、市场结构）</td><td>资料分析·速算：截位直除</td><td>同上</td></tr><tr><td>周四 11/19</td><td>经济·国际经济（汇率、国际贸易）</td><td>资料分析·速算：百化分（背 1/2–1/20 互换表）</td><td>同上</td></tr><tr><td>周五 11/20</td><td>经济全章错题</td><td>资料分析·先看选项再算 + 3 篇限时</td><td>同上</td></tr><tr><td>周六 11/21</td><td>经济清单默写</td><td>资料分析 3 篇限时</td><td>19:00–20:00 作文 1 篇</td></tr><tr><td>周日 11/22</td><td>改错 2 篇 + 错题重做</td><td>休息</td><td>作文自评 + 素材库</td></tr></tbody></table><h3 id="w8-11-23–11-29-公基-公文-职业道德-人文国情-职测-资料限时-数字推理入门" tabindex="-1">W8（11/23–11/29）公基：公文 + 职业道德 + 人文国情｜职测：资料限时 + 数字推理入门 <a class="header-anchor" href="#w8-11-23–11-29-公基-公文-职业道德-人文国情-职测-资料限时-数字推理入门" aria-label="Permalink to &quot;W8（11/23–11/29）公基：公文 + 职业道德 + 人文国情｜职测：资料限时 + 数字推理入门&quot;">​</a></h3><table tabindex="0"><thead><tr><th>日期</th><th>上午（公基）</th><th>下午（职测）</th><th>晚上 / 备注</th></tr></thead><tbody><tr><td>周一 11/23</td><td>公文·文种适用范围（15 种法定公文）</td><td>资料分析 3 篇限时</td><td>错题归因 + 默写</td></tr><tr><td>周二 11/24</td><td>公文·格式要素（版头 / 主体 / 版记）+ 行文规则</td><td>资料分析 3 篇限时</td><td>同上</td></tr><tr><td>周三 11/25</td><td>公文·改错专项（格式 + 内容 + 逻辑三层）</td><td>数字推理·作差、作和</td><td>同上</td></tr><tr><td>周四 11/26</td><td>职业道德（事业单位工作人员职业道德规范）</td><td>数字推理·作商、作积</td><td>同上</td></tr><tr><td>周五 11/27</td><td>人文、科技、国情（用李梦娇口诀快速过）</td><td>数字推理·幂次修正、拆项分组</td><td>同上</td></tr><tr><td>周六 11/28</td><td>公文格式对照表默画 + 人文清单</td><td>数字推理 10 题</td><td>19:00–20:00 作文 1 篇</td></tr><tr><td>周日 11/29</td><td><strong>检查点一</strong>：公基过完一遍了吗？作文够 7 篇吗？</td><td>错题大重做</td><td>定强化期计划</td></tr></tbody></table><hr><h2 id="六、强化期任务包-w9–w25-11-30–3-28" tabindex="-1">六、强化期任务包（W9–W25，11/30–3/28） <a class="header-anchor" href="#六、强化期任务包-w9–w25-11-30–3-28" aria-label="Permalink to &quot;六、强化期任务包（W9–W25，11/30–3/28）&quot;">​</a></h2><p><strong>每天怎么拆</strong>：周一至周五上午 3 小时推进本周公基板块（把板块内容平均分成 5 份）；下午 3 小时做本周职测模块（每天固定题量）；周六照常 + 晚上作文 1 篇；周日上午改错 2 篇 + 错题重做，下午休息，晚上定计划。</p><table tabindex="0"><thead><tr><th>周</th><th>日期</th><th>公基（上午）</th><th>职测（下午）</th><th>每天题量</th></tr></thead><tbody><tr><td>9</td><td>11/30–12/6</td><td>政治二轮·马原 + 毛概</td><td>言语专项</td><td>30 题</td></tr><tr><td>10</td><td>12/7–12/13</td><td>政治二轮·中特 + 习思想</td><td>言语专项</td><td>30 题</td></tr><tr><td>11</td><td>12/14–12/20</td><td>政治二轮·时政 + 错题</td><td>判断·图推加倍</td><td>20 题</td></tr><tr><td>12</td><td>12/21–12/27</td><td>法律二轮·宪法 / 行政法</td><td>判断·定义 / 类比</td><td>20 题</td></tr><tr><td>13</td><td>12/28–1/3</td><td>法律二轮·民法 / 刑法</td><td>判断·逻辑</td><td>20 题 + <strong>每周 2 套整卷</strong></td></tr><tr><td>14</td><td>1/4–1/10</td><td>法律二轮·诉讼法 / 公司法</td><td>资料分析</td><td>3 篇限时；<strong>第 1 次人工精批</strong></td></tr><tr><td>15</td><td>1/11–1/17</td><td>经济二轮</td><td>资料·速度攻坚</td><td>3 篇限时</td></tr><tr><td>16</td><td>1/18–1/24</td><td>经济二轮</td><td>数量·高频 6 类</td><td>10 题</td></tr><tr><td>17</td><td>1/25–1/31</td><td>公文二轮·改错实战</td><td>数量·数字推理</td><td>10 题</td></tr><tr><td>18</td><td>2/1–2/7</td><td><strong>春节·降强度</strong>：只跟时政 + 作文</td><td>—</td><td>—</td></tr><tr><td>19</td><td>2/8–2/14</td><td>公文收尾 + 人文科技国情</td><td>常识判断 + 弱项</td><td>随公基</td></tr><tr><td>20</td><td>2/15–2/21</td><td>政治 + 法律·错题三刷</td><td>言语 + 判断·速度攻坚</td><td>套卷</td></tr><tr><td>21</td><td>2/22–2/28</td><td>政治 + 法律·错题三刷</td><td>言语 + 判断·速度攻坚</td><td><strong>加每周 1 次全套模拟</strong></td></tr><tr><td>22</td><td>3/1–3/7</td><td>经济 + 公文·错题三刷</td><td>资料 + 数量·速度攻坚</td><td>2 套 + 1 模考</td></tr><tr><td>23</td><td>3/8–3/14</td><td>经济 + 公文·错题三刷</td><td>资料 + 数量·速度攻坚</td><td>2 套 + 1 模考</td></tr><tr><td>24</td><td>3/15–3/21</td><td>全科串讲</td><td>全科限时套卷</td><td>2 套 + 1 模考</td></tr><tr><td>25</td><td>3/22–3/28</td><td>全科串讲 + 弱点攻坚</td><td>全科限时套卷</td><td><strong>检查点二</strong></td></tr></tbody></table><p><strong>强化期主观题</strong>：每周六作文 1 篇（累计到 W25 约 24 篇）；每周日改错 2–3 篇（累计约 52 篇）。</p><hr><h2 id="七、冲刺期任务包-w26–w34-3-29–5-30" tabindex="-1">七、冲刺期任务包（W26–W34，3/29–5/30） <a class="header-anchor" href="#七、冲刺期任务包-w26–w34-3-29–5-30" aria-label="Permalink to &quot;七、冲刺期任务包（W26–W34，3/29–5/30）&quot;">​</a></h2><p><strong>每天怎么拆</strong>：上午两套整卷（职测 90 分钟 + 公基 90 分钟），下午对答案逐题精析，晚上时政或作文主题。考前两周只看错题本，不做新题。</p><table tabindex="0"><thead><tr><th>周</th><th>日期</th><th>本周任务</th></tr></thead><tbody><tr><td>26</td><td>3/29–4/4</td><td>近 4 年河南联考真题第一遍（职测 + 公基各 2 套）</td></tr><tr><td>27</td><td>4/5–4/11</td><td>同上 + 逐题精析、错题归因</td></tr><tr><td>28</td><td>4/12–4/18</td><td>同上；<strong>第 2 次人工精批</strong></td></tr><tr><td>29</td><td>4/19–4/25</td><td>邻省真题；<strong>公告预计发布，下载岗位表按专业筛选</strong>（见配套文件的 §5.3）</td></tr><tr><td>30</td><td>4/26–5/2</td><td><strong>报名（预计 4/24–4/30）</strong>：选岗、<strong>打电话确认专业后再提交</strong></td></tr><tr><td>31</td><td>5/3–5/9</td><td><strong>盯核减公告（可能 5/7），留意 8 小时改报窗口</strong>；河南真题第二遍（只做错题）</td></tr><tr><td>32</td><td>5/10–5/16</td><td>时政冲刺（近半年过 3 遍）+ 作文押题；<strong>第 3–5 次人工精批</strong></td></tr><tr><td>33</td><td>5/17–5/23</td><td>考前一周：<strong>不做新题</strong>，只看错题本 + 框架笔记 + 素材库；打印准考证、踩点</td></tr><tr><td>34</td><td>5/24–5/30</td><td>笔试周。<strong>考完当天开始练结构化面试</strong></td></tr></tbody></table><hr><h2 id="八、检查点" tabindex="-1">八、检查点 <a class="header-anchor" href="#八、检查点" aria-label="Permalink to &quot;八、检查点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>检查点</th><th>时间</th><th>达标标准</th><th>没达到怎么办</th></tr></thead><tbody><tr><td>一</td><td>11/29（W8）</td><td>公基过完一遍；作文 ≥7 篇</td><td>用 W9 补，政治三轮压缩 1 周</td></tr><tr><td>二</td><td>3/28（W25）</td><td>整卷模考稳定 65 分</td><td>W26–27 专攻最弱模块，真题量减半</td></tr><tr><td>三</td><td>5/9（W31）</td><td>真题正确率稳定</td><td><strong>放弃数量关系</strong>，全力保其他</td></tr></tbody></table><p><strong>调整原则：先砍公基的知识输入，绝不砍作文和改错。</strong></p><hr><h2 id="九、开工前一次性准备-花半天做完" tabindex="-1">九、开工前一次性准备（花半天做完） <a class="header-anchor" href="#九、开工前一次性准备-花半天做完" aria-label="Permalink to &quot;九、开工前一次性准备（花半天做完）&quot;">​</a></h2><p>教材已经到了，先花半天做这几件事，之后再不用操心：</p><ul><li>[ ] 把公基、职测两套书的<strong>目录</strong>和马克的视频合集列表摊开，建一张对照表（见配套文件 §4.3），贴在框架笔记扉页。<strong>这一步做完，以后每周打开计划就知道翻哪册第几页、听哪几集</strong></li><li>[ ] 准备 A4 活页本（框架笔记）+ 彩色隔页纸 + 黑蓝红三色笔 + 一个 A5 小本（错题本）</li><li>[ ] 手机装好：粉笔 App（买会员用）、半月谈 App（薅免费 AI 批改 5 次）</li><li>[ ] B站关注：公考李梦娇、马克 Mark、刘文超 Vin、公考齐麟、公考李致、醒醒最厉害</li><li>[ ] B站先看两节破冰课：「醒醒最厉害」的大作文结构课、「公考李致」的公文改错课前 3 集</li></ul><p><strong>然后就进 W1。<strong>不必严格对齐星期几——从 W1 那张表的「周一」那一格开始往下做就行，做到「周日」那一格算一周结束。如果实际日期和表里的日期对不上，以</strong>顺序</strong>为准，不用改表。</p><blockquote><p>唯一要对齐的是「周六写作文、周日上午改错、周日下午休息」这个节奏，因为它关系到休息和复盘。如果开工那天是周三，就把那一周压缩成 5 天，从下周一再正式起周。</p></blockquote>`,75)])])}const g=d(s,[["render",e]]);export{c as __pageData,g as default};
